INSERT INTO `page_text` (`ID`,`Text`,`NextPageID`,`PlayerConditionID`,`Flags`,`VerifiedBuild`) VALUES
(10732,'<You touch the small white crystal and you can hear faint sounds on the wind. This is an audio recording of some sort.>\r\n\r\n"The Rebellion in Eldre\'Thalas, Part 1"',10733,0,0,70124),
(10733,'"In the days immediately following the turmoil at the Well of Eternity, there was much unrest in Eldre\'Thalas. The demonic forces that poured from the Well nearly overwhelmed the beleaguered elvish kingdoms, ravaging the land and killing indiscriminately. If not for the intervention of the demigod Goldrinn and the sacrifice of countless kaldorei heroes, the kingdom of Eldre\'Thalas would surely have been overrun and destroyed."',10734,0,0,70124),
(10734,'"After the climax of the war and the Great Sundering of Kalimdor, the new reality of a world bereft of the sustaining magic on which our people depended quickly became apparent. The ruling house of Eldre\'Thalas--House Tortheldrin--rapidly set plans in motion to ensure stability and continuity of our way of life. However, the methods they intended to employ left many deeply concerned."',10735,0,0,70124),
(10735,'"The young Prince Tortheldrin intended to build a network of crystalline foci and use them to siphon and shape a new font of power for our people to draw upon. The point of contention for many was that he intended to use the very power that nearly destroyed our world to accomplish this. He meant to siphon this power from a demon world within the Twisting Nether itself. \r\n\r\nMany rightly feared this could open a new door through which demonic entities might gain once again access to our world."',0,0,0,70124);
